import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import java.util.TreeMap;

/**
 * Deterministic, headless replica of Simulator's populate + step loop.
 * Used to prove refactors are behaviour-preserving: same seed -> identical signature.
 * NOT part of the application; deleted after verification.
 */
public class VerifyHarness {

	interface Factory { Animal make(Field f, Location l); }

	public static void main(String[] args) {
		int depth = 200, width = 320;
		Random rand = Randomizer.getRandom();
		Field field = new Field(depth, width);
		Climate climate = new Climate(Weather.SUN);
		List<Animal> animals = new ArrayList<>();
		List<Plant> plants = new ArrayList<>();

		double[] probs = {0.07, 0.07, 0.07, 0.03, 0.03};
		Factory[] facs = {
				(f, l) -> new Bird(true, f, l),
				(f, l) -> new Mouse(true, f, l),
				(f, l) -> new Duck(true, f, l),
				(f, l) -> new Wolf(true, f, l),
				(f, l) -> new Bear(true, f, l),
		};

		field.clear();
		for (int row = 0; row < depth; row++) {
			for (int col = 0; col < width; col++) {
				Location loc = new Location(row, col);
				plants.add(rand.nextDouble() <= 0.07 ? new Flower(field, loc) : new Grass(field, loc));
				for (int i = 0; i < probs.length; i++) {
					if (rand.nextDouble() <= probs[i]) { animals.add(facs[i].make(field, loc)); break; }
				}
			}
		}

		TimeCycle cycle = TimeCycle.DAY;
		int step = 0;
		StringBuilder sig = new StringBuilder();
		for (int s = 1; s <= 160; s++) {
			step++;
			climate.updateClimate(step);
			for (Plant p : plants) p.increaseStage(climate);
			List<Animal> born = new ArrayList<>();
			for (Animal a : animals) a.act(born, cycle);
			animals.removeIf(a -> !a.isAlive());
			animals.addAll(born);
			if (step % 4 == 0) cycle = cycle.next();

			if (s % 10 == 0) {
				TreeMap<String, Integer> counts = new TreeMap<>();
				int sick = 0;
				for (Animal a : animals) {
					counts.merge(a.getClass().getSimpleName(), 1, Integer::sum);
					if (a.isSick()) sick++;
				}
				sig.append(String.format("s=%d pop=%d %s sick=%d season=%s wx=%s hum=%d cyc=%s%n",
						s, animals.size(), counts, sick,
						climate.getCurrentSeason(), climate.getCurrentWeather(), climate.getHumidity(), cycle));
			}
		}
		System.out.print(sig);
	}
}

